Here is a simple C++ class implementation for a 2D point:

```cpp
#include <iostream>

class Point {
private:
    double x;
    double y;

public:
    // Constructor
    Point(double xVal = 0.0, double yVal = 0.0) : x(xVal), y(yVal) {}

    // Getters
    double getX() const { return x; }
    double getY() const { return y; }

    // Setters
    void setX(double xVal) { x = xVal; }
    void setY(double yVal) { y = yVal; }

    // Display method
    void print() const {
        std::cout << "(" << x << ", " << y << ")" << std::endl;
    }
};

int main() {
    Point p1(3.5, 4.2);
    p1.print();

    p1.setX(10.0);
    p1.setY(20.0);
    p1.print();

    return 0;
}
```

