<?php

function getFirstKCharacters($s, $k) {
    // Ensure k is not greater than the length of the string
    if ($k > strlen($s)) {
        $k = strlen($s);
    }

    // Return the first k characters
    return substr($s, 0, $k);
}

// Example usage
$string = "SoftwareTestingHelp";
$integer = 6;

$result = getFirstKCharacters($string, $integer);
echo $result; // Output: Softwa

?>
